	@Test
	@Timeout(value = 2, unit = TimeUnit.HOURS)
	void allThemeQueriesReturnExpectedResultsAndPublishClassifiedFrontierEvidence(@TempDir Path dataDirectory) {
		executeThemeCoverage(dataDirectory);
	}

	private static void executeThemeCoverage(Path dataDirectory) {
		int executedQueries = 0;
		List<String> coverageFailures = new ArrayList<>();
		List<Theme> themes = selectedThemes();
		List<Integer> queryIndexes = selectedQueryIndexes();
		SailRepository scalarRepository = repository(dataDirectory.resolve("scalar"), FrontierEstimatorMode.OFF);
		SailRepository frontierRepository = repository(dataDirectory.resolve("frontier"),
				FrontierEstimatorMode.AUTHORITATIVE);
		try {
			loadBoundedThemeData(scalarRepository, themes);
			loadBoundedThemeData(frontierRepository, themes);
			assertEquals(FrontierStatisticsAvailability.READY,
					((LmdbStore) frontierRepository.getSail()).rebuildFrontierStatistics().availability(),
					"The Theme coverage run must exercise an authoritative Frontier synopsis");
			try (SailRepositoryConnection scalarConnection = scalarRepository.getConnection();
					SailRepositoryConnection frontierConnection = frontierRepository.getConnection()) {
				for (Theme theme : themes) {
					for (int queryIndex : queryIndexes) {
						String query = ThemeQueryCatalog.queryFor(theme, queryIndex);
						String queryKey = theme + " q" + queryIndex;
						ResultBag scalarRows = evaluate(scalarConnection, query, queryKey + " scalar");
						Explanation explanation = frontierConnection
								.prepareTupleQuery(query)
								.explain(Explanation.Level.Optimized);
						ResultBag frontierRows = evaluate(frontierConnection, query, queryKey + " Frontier");
						assertEquals(scalarRows, frontierRows,
								() -> queryKey + " changed SPARQL bag results when Frontier became authoritative"
										+ diagnosticRows(scalarConnection, frontierConnection, query, queryKey)
										+ "\nScalar plan:\n"
										+ scalarConnection.prepareTupleQuery(query)
												.explain(Explanation.Level.Optimized)
												.tupleExpr()
										+ "\nFrontier plan:\n" + explanation.tupleExpr());
						auditFrontierCoverage(theme, queryIndex, (TupleExpr) explanation.tupleExpr(),
								coverageFailures);
						executedQueries++;
					}
				}
			}
		} finally {
			frontierRepository.shutDown();
			scalarRepository.shutDown();
		}

		assertTrue(coverageFailures.isEmpty(), () -> String.join("\n", coverageFailures));
		assertEquals(themes.size() * queryIndexes.size(), executedQueries, "Every selected theme query must execute");
	}

	private static SailRepository repository(Path dataDirectory, FrontierEstimatorMode mode) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setFrontierEstimatorMode(mode)
				.setFrontierSynopsisBudgetBytes(mode == FrontierEstimatorMode.OFF ? 0L : 32L * 1024L * 1024L);
		SailRepository repository = new SailRepository(new LmdbStore(dataDirectory.toFile(), config));
		repository.init();
		return repository;
	}

	private static void loadBoundedThemeData(SailRepository repository, List<Theme> themes) {
		for (Theme theme : themes) {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				generateBoundedTheme(theme, new RDFInserter(connection));
				connection.commit();
			}
		}
	}

